[=[return {c={"Typeface","Size and weight","Status bar texture","Where it goes"},e={{"c","Typeface",1,1},{"r","Barlow Semi Condensed",1,1},{"c","Size and weight",1,2},{"r","Size adjustment",1,2},{"d","Size adjustment",1,2,"Shifts every font object relative to its stock size, so the difference between a header and body text is preserved."},{"t","Outlined text",1,2,"Outlines keep text legible over the world and over bright bar textures. Turn it off for a softer look on dark panels only."},{"r","Outlined text",1,2},{"d","Outlined text",1,2,"Outlines keep text legible over the world and over bright bar textures."},{"c","Status bar texture",2,3},{"t","Status bar texture",2,3,"The fill of every HEALTH, POWER, CAST and METER bar: unit frames, nameplates, the meter, the HUD, loot rolls, the tooltip health bar and the Blizzard frames ZacUI skins. Not the action bars - how buttons look lives under Action bars. Bars already on screen change at once; a bar skinned at login that is not up right now takes it when it next appears."},{"r","ZacUI default (gradient)",2,3},{"d","ZacUI default (gradient)",2,3,"The fill of every HEALTH, POWER, CAST and METER bar: unit frames, nameplates, the meter, the HUD, loot rolls, the tooltip health bar and the Blizzard frames ZacUI skins."},{"c","Where it goes",3,4},{"t","Where it goes",3,4,"Every text ZacUI draws - every part, every aura, every skinned Blizzard frame - and Readycheck's too, is in the font above, always. These keep a bar texture of their own and are handed the one above whenever you change it, while ticked. Un-tick one to set its texture by hand on its own page."},{"d","Where it goes",3,4,"Every text ZacUI draws - every part, every aura, every skinned Blizzard frame - and Readycheck's too, is in the font above, always."},{"r","Unit frames",3,4},{"r","Frame font, bar texture and name-strip texture.",3,4},{"r","Nameplates",3,4},{"r","Plate font, health bar and cast bar textures.",3,4},{"r","Action bar text",3,4},{"r","Key, count and macro text on every bar that has no font of its own.",3,4},{"r","Meter",3,4},{"r","Row font and bar texture in the damage and threat windows.",3,4},{"r","Raid mods",3,4},{"d","Raid mods",3,4,"The boss mods' bars (always) and texts (unless the Raid mods page picks a font of its own)."},{"t","Readycheck (not loaded)",3,4,"Readycheck's bar texture. Its font is always ZacUI's, ticked or not, so the two addons match."},{"r","Readycheck (not loaded)",3,4},{"r","Readycheck's bar texture.",3,4},{"t","Apply to ticked now",3,4,"Pushes the current font and texture into every ticked target again."},{"r","Apply to ticked now",3,4},{"t","Texture into auras...",3,4,"Rewrites the texture of every bar in your auras. A button, not automatic: it edits each aura's saved data. Their texts need nothing: they always use ZacUI's font."},{"r","Texture into auras...",3,4},{"d","Texture into auras...",3,4,"Rewrites the texture of every bar in your auras. A button, not automatic: it edits each aura's saved data. Their texts need nothing: they always use ZacUI's font."},{"b","Font",1,0},{"b","Bar texture",2,0},{"b","Where it goes",3,0}},t={{"font","Font"},{"texture","Bar texture"},{"where","Where it goes"}}}]=],
