,{"t","Diagnose",6,16,"Prints which minimap pieces this client actually has, and whether each one is where you asked for it. Several of them changed names in 11509."},{"t","Reset",6,16,"Puts every option on this page back to the default."},{"r","Diagnose",6,16},{"r","Reset",6,16},{"c","Button tray",7,17},{"d","Button tray",7,17,"Collects every addon's minimap button into one bar, so the minimap stays a map."},{"c","Collecting",7,18},{"r","Use ZacUI's button tray",7,18},{"d","Use ZacUI's button tray",7,18,"Turning it off puts every button back exactly where it was - position, size and all were recorded before anything moved."},{"r","0 buttons collected",7,18},{"r","Open on hover",7,18},{"r","Off means the tray only opens when you click the bar.",7,18},{"c","Where it sits",7,19},{"t","Where",7,19,"Its own bar is a thin bar anywhere on the screen that opens a tray. Left, right, above or under: a strip along that edge of the map. On the minimap: smaller buttons in a band on the map itself. A tab: a small tab with the number of buttons that opens a grid. All of them move and scale with the map."},{"r","Left of the minimap",7,19},{"r","Where",7,19},{"r","Its own bar is a thin bar anywhere on the screen that opens a tray.",7,19},{"t","Lock the bar in place",7,19,"Drag the bar with the left mouse button to move it. Right-click it at any time to come back to this page."},{"r","Lock the bar in place",7,19},{"r","Drag the bar with the left mouse button to move it.",7,19},{"t","Reset position",7,19,"Puts the bar back at the top centre of the screen."},{"r","Reset position",7,19},{"c","Look",7,20},{"r","Button size",7,20},{"r","Columns",7,20},{"r","Space between buttons",7,20},{"r","Space around the edge",7,20},{"t","Uniform square icons",7,20,"Crops each addon's icon out of its own ring and puts it on a ZacUI plate, so the tray reads as one row rather than a jumble. A button whose icon cannot be identified is left alone rather than stripped - turn this off if one still comes out wrong."},{"r","Uniform square icons",7,20},{"d","Uniform square icons",7,20,"Crops each addon's icon out of its own ring and puts it on a ZacUI plate, so the tray reads as one row rather than a jumble."},{"r","Tray background",7,20},{"r","Tray border",7,20},{"c","Button layout",7,21},{"r","Buttons in the tray",7,21},{"r","Grows",7,21},{"r","New lines go",7,21},{"r","Default (Right)",7,21},{"r","Default (Down)",7,21},{"r","Per line (0 = one line)",7,21},{"r","Gap across",7,21},{"r","Padding",7,21},{"r","Gap down",7,21},{"r","Reverse the order",7,21},{"d","Reverse the order",7,21,"Which way the buttons fill the tray. Nothing changed here = the columns and spaces above."},{"c","The bar",7,22},{"r","Bar colour",7,22},{"r","Bar width",7,22},{"r","Bar height",7,22},{"r","Bar opacity at rest",7,22},{"d","Bar opacity at rest",7,22,"The bar goes fully opaque on hover regardless, so it can sit almost invisible until you reach for it."},{"c","Opening and closing",7,23},{"r","When the tray opens",7,23},{"r","Style",7,23},{"r","None",7,23},{"r","Duration",7,23},{"r","Delay",7,23},{"r","Easing",7,23},{"t","Repeat until hidden",7,23,"Pulse and Flash only: keep playing for as long as the frame is shown."},{"r","Repeat until hidden",7,23},{"r","Smooth",7,23},{"r","Comes from",7,23},{"r","Distance",7,23},{"r","Below",7,23},{"r","None opens it at once, as it always has.",7,23},{"r","When the tray closes",7,23},{"r","Style",7,23},{"r","None",7,23},{"r","Duration",7,23},{"r","Delay",7,23},{"r","Easing",7,23},{"t","Repeat until hidden",7,23,"Pulse and Flash only: keep playing for as long as the frame is shown."},{"r","Repeat until hidden",7,23},{"r","Smooth",7,23},{"r","Comes from",7,23},{"r","Distance",7,23},{"r","Above",7,23},{"r","None puts it away at once, as it always has.",7,23},{"r","Close after",7,23},{"r","How long the tray waits once the mouse leaves it.",7,23},{"c","Tools",7,16},{"t","Scan now",7,16,"Addons add their minimap button whenever they feel like it. ZacUI rescans automatically, but this does it immediately."},{"r","Scan now",7,16},{"r","Diagnose",7,16},{"b","General",1,0},{"b","Look",2,0},{"b","Text",3,0},{"b","Animation",4,0},{"b","Position",5,0},{"b","Advanced",6,0},{"b","Button tray",7,0}},t={{"general","General"},{"look","Look"},{"text","Text"},{"anim","Animation"},{"pos","Position"},{"adv","Advanced"},{"tray","Button tray"}}}]=],
[=[return {c={"Everything in this group","Engine","How toggling behaves"},e={{"c","Everything in this group",0,1},{"r","Enable all",0,1},{"r","Disable all",0,1},{"c","Engine",0,2},{"r","Font system",0,2},{"r","Applies your font face, size and outline to Blizzard's font objects.",0,2},{"r","Frame watcher",0,2},{"d","Frame watcher",0,2,"Classifies frames the moment they are born, so nothing appears unstyled."},{"r","Hooks",0,2},{"r","Self-skinning hooks on scroll frames, dropdowns and tabs.",0,2},{"r","Login sweep",0,2},{"r","One classifier pass over everything alive at login.",0,2},{"c","How toggling behaves",0,3},{"d","How toggling behaves",0,3,"Turning a module ON applies it immediately. Turning one OFF needs a reload, because skinning strips Blizzard's artwork and there is nothing left to put back - ZacUI will not pretend otherwise."}},t={}}]=],
[=[return {c={"Everything in this group","HUD","How toggling behaves"},e={{"c","Everything in this group",0,1},{"r","Enable all",0,1},{"r","Disable all",0,1},{"c","HUD",0,2},{"t","Action bars",0,2,"ZacUI's own action bars: ten bars, pet and stance bars, bags, micro menu and XP strip, each placed, scaled, paged and faded from the Action bars page. Replaces Bartender4 and imports its settings. Stands down while Bartender4 is enabled."},{"r","Action bars",0,2},{"d","Action bars",0,2,"ZacUI's own action bars: ten bars, pet and stance bars, bags, micro menu and XP strip, each placed, scaled, paged and faded from the Action bars page."},{"t","Action bars (Blizzard)",0,2,"Skins Blizzard's action buttons, pet and stance bars, the bar art and the micro menu. Only visible when the ZacUI action bars are off."},{"r","Action bars (Blizzard)",0,2},{"d","Action bars (Blizzard)",0,2,"Skins Blizzard's action buttons, pet and stance bars, the bar art and the micro menu."},{"r","Buffs",0,2},{"r","Buff, debuff and weapon-enchant buttons.",0,2},{"t","Button tray",0,2,"Sweeps every addon's minimap button into one movable bar with a flyout tray. Replaces ButtonStash."},{"r","Button tray",0,2},{"d","Button tray",0,2,"Sweeps every addon's minimap button into one movable bar with a flyout tray."},{"r","Cast bars",0,2},{"r","Player, target and mirror (breath / fatigue) bars.",0,2},{"t","Chat",0,2,"Chat windows on dark panels with flat tabs, plus a bar under the docked chat: channel buttons, a whisper counter, and the numbers you pick (durability, bag space, gold, latency...). The edit box opens in that bar. Fine-tune on the Chat page."},{"r","Chat",0,2},{"d","Chat",0,2,"Chat windows on dark panels with flat tabs, plus a bar under the docked chat: channel buttons, a whisper counter, and the numbers you pick (durability, bag space, gold, latency...)."},{"t","Damage meter",0,2,"ZacUI's own damage meter and threat display. Replaces Details! and TinyThreat; windows, skin and formulas are the ported Naowh setup. Fine-tune on the Damage meter page."},{"r","Damage meter",0,2},{"r","ZacUI's own damage meter and threat display.",0,2},{"t","Minimap",0,2,"A square minimap in one ZacUI frame: zone name header, friends / clock / guild footer, coordinates, and the mail, tracking and battleground icons tucked into its corners. Wheel zoom."},{"r","Minimap",0,2},{"d","Minimap",0,2,"A square minimap in one ZacUI frame: zone name header, friends / clock / guild footer, coordinates, and the mail, tracking and battleground icons tucked into its corners."},{"t","Nameplates",0,2,"ZacUI's own nameplate engine: health, cast bars, auras and threat colors. Replaces Plater; defaults are the ported Naowh profile. Fine-tune on the Nameplates page."},{"r","Nameplates",0,2},{"d","Nameplates",0,2,"ZacUI's own nameplate engine: health, cast bars, auras and threat colors."},{"t","Quality of life",0,2,"Auto sell junk, auto repair, gossip skipping, faster looting, whisper invites, error dismounting, screen effect removal and sound muting. Replaces Leatrix Plus; defaults are your audited Leatrix setup. Fine-tune on the Quality of life page."},{"r","Quality of life",0,2},{"d","Quality of life",0,2,"Auto sell junk, auto repair, gossip skipping, faster looting, whisper invites, error dismounting, screen effect removal and sound muting."},{"r","Quest tracker",0,2},{"r","The objectives watch frame.",0,2},{"r","Tooltips",0,2},{"r","Every tooltip in the game, plus a movable anchor.",0,2},{"r","Unit frames",0,2},{"r","Player, target, pet, party and their status bars.",0,2},{"c","How toggling behaves",0,3},{"d","How toggling behaves",0,3,"Turning a module ON applies it immediately. Turning one OFF needs a reload, because skinning strips Blizzard's artwork and there is nothing left to put back - ZacUI will not pretend otherwise."}},t={}}]=],
[=[return {c={"Everything in this group","Windows","How toggling behaves"},e={{"c","Everything in this group",0,1},{"r","Enable all",0,1},{"r","Disable all",0,1},{"c","Windows",0,2},{"r","Addon list",0,2},{"d","Addon list",0,2,"The AddOn List window (Esc > AddOns): panel chrome, the four buttons, character dropdown, search box and its scroll bars."},{"t","Auction house",0,2,"Search, Sell and Cancel tabs with a price memory built from what you browse. Stands down if Auctionator is loaded."},{"r","Auction house",0,2},{"d","Auction house",0,2,"Search, Sell and Cancel tabs with a price memory built from what you browse."},{"t","Bags (Blizzard)",0,2,"Skins Blizzard's separate bag frames. Only does anything when the combined bag is off."},{"r","Bags (Blizzard)",0,2},{"r","Skins Blizzard's separate bag frames.",0,2},{"r","Bank",0,2},{"r","Bank frame, bag slots and purchase prompt.",0,2},{"r","Battlemaster",0,2},{"d","Battlemaster",0,2,"The battlemaster window: instance list with queue status, the battleground's description, and Join / Join as group / Cancel through Blizzard's own buttons."},{"t","Character (Blizzard)",0,2,"Skins Blizzard's character window and its pages. Mostly covered by the ZacUI pages above; still styles anything they leave."},{"r","Character (Blizzard)",0,2},{"r","Skins Blizzard's character window and its pages.",0,2},{"t","Character sheet",0,2,"ZacUI's own character sheet: gear in two flat columns with quality borders, item levels, wear and cooldowns, a rotatable and zoomable 3D model, two stat cards you choose, average item level, durability and helm / cloak toggles. Every click works like Blizzard's slots, including right-click to use."},{"r","Character sheet",0,2},{"d","Character sheet",0,2,"ZacUI's own character sheet: gear in two flat columns with quality borders, item levels, wear and cooldowns, a rotatable and zoomable 3D model, two stat cards you choose, average item level, durability and helm / cloak toggles."},{"t","Character tabs",0,2,"The Character / Pet / Reputation / Skills / Honor tabs as full-size ZacUI tabs, flush under the character window. They click Blizzard's own tabs underneath, so switching page still works in combat."},{"r","Character tabs",0,2},{"d","Character tabs",0,2,"The Character / Pet / Reputation / Skills / Honor tabs as full-size ZacUI tabs, flush under the character window."},{"t","Combined bag",0,2,"One window for every bag, with search, sorting and quality borders. Replaces Blizzard's one-frame-per-bag layout, and stands down if another bag addon is loaded."},{"r","Combined bag",0,2},{"r","One window for every bag, with search, sorting and quality borders.",0,2},{"r","Enchanting",0,2},{"r","The same wide profession window for Enchanting and Beast Training.",0,2},{"t","Flight map (Blizzard)",0,2,"Skins Blizzard's flight map. Only visible when the ZacUI flight master window is off."},{"r","Flight map (Blizzard)",0,2},{"r","Skins Blizzard's flight map.",0,2},{"t","Flight master",0,2,"ZacUI's own flight master window: a bigger flight map beside a searchable list of every place you can fly to, with zone, cost and stops. Hover a destination to see its route, click to fly; a Cheapest filter sorts by cost."},{"r","Flight master",0,2},{"d","Flight master",0,2,"ZacUI's own flight master window: a bigger flight map beside a searchable list of every place you can fly to, with zone, cost and stops."},{"r","Friends",0,2},{"d","Friends",0,2,"ZacUI's own friends list: search, online-only filter, class colours, status, zone and note, with Blizzard's right-click menu."},{"r","Game menu",0,2},{"r","The Esc menu and its buttons.",0,2},{"t","Gossip",0,2,"ZacUI's own gossip window: what the NPC says above one list of available quests, current quests and gossip options. Clicks, Goodbye and the X do exactly what Blizzard's do."},{"r","Gossip",0,2},{"d","Gossip",0,2,"ZacUI's own gossip window: what the NPC says above one list of available quests, current quests and gossip options."},{"t","Group finder",0,2,"ZacUI's own Looking For Group window: list your group for any mix of activities with roles and a comment, or browse listings with category and activity filters, search and solo / group chips. Whisper and invite work like Blizzard's."},{"r","Group finder",0,2},{"d","Group finder",0,2,"ZacUI's own Looking For Group window: list your group for any mix of activities with roles and a comment, or browse listings with category and activity filters, search and solo / group chips."},{"r","Guild (Blizzard)",0,2},{"r","Guild control panel, member details and the guild bank.",0,2},{"t","Guild roster",0,2,"ZacUI's own guild roster: search, online-only filter, MOTD, notes and officer notes, last online. Clicking a member opens Blizzard's member panel."},{"r","Guild roster",0,2},{"d","Guild roster",0,2,"ZacUI's own guild roster: search, online-only filter, MOTD, notes and officer notes, last online."},{"r","Honor",0,2},{"d","Honor",0,2,"ZacUI's Honor page: rank, rank progress, and kills and honor for today, yesterday, this week, last week and lifetime."},{"r","Ignore list",0,2},{"r","A searchable ignore list with Ignore Player and Remove buttons.",0,2},{"r","Inspect",0,2},{"r","The inspect window.",0,2},{"r","Inspect",0,2},{"d","Inspect",0,2,"A wider ZacUI inspect window: the player's gear with item names and levels, their model, average item level, and their honor page."},{"t","Loot",0,2,"ZacUI's own loot window: every slot in one list with quality borders, counts, quest marks and a Loot all button. Opens under the cursor like Blizzard's; master loot, bind prompts and shift / ctrl-click all still apply."},{"r","Loot",0,2},{"d","Loot",0,2,"ZacUI's own loot window: every slot in one list with quality borders, counts, quest marks and a Loot all button."},{"r","Loot",0,2},{"r","Loot window and the master looter frame.",0,2},{"t","Loot rolls",0,2,"Group loot rolls rebuilt as compact ElvUI-style bars: item icon, quality-colored timer, need/greed/pass with live roll counts and roller tooltips. Movable under Movers; /zui testroll shows fakes to place them by."},{"r","Loot rolls",0,2},{"d","Loot rolls",0,2,"Group loot rolls rebuilt as compact ElvUI-style bars: item icon, quality-colored timer, need/greed/pass with live roll counts and roller tooltips."},{"r","Macros",0,2},{"d","Macros",0,2,"A searchable macro list and a full editor: icon picker, character counter, duplicate and unsaved-changes protection."},{"r","Mail (Blizzard)",0,2},{"d","Mail (Blizzard)",0,2,"Skins Blizzard's mail window: the send page, the open letter, and the inbox when the ZacUI mailbox is off."},{"r","Mail tabs",0,2},{"r","The Inbox / Send Mail tabs as ZacUI tabs, flush under the mailbox.",0,2},{"t","Mailbox",0,2,"ZacUI's own inbox: every mail in one searchable list with money, items and COD filters, a throttled Collect all, and right-click to empty one mail. C.O.D. mail is never paid automatically."},{"r","Mailbox",0,2},{"d","Mailbox",0,2,"ZacUI's own inbox: every mail in one searchable list with money, items and COD filters, a throttled Collect all, and right-click to empty one mail."},{"t","Maps",0,2,"Makes the map a movable, resizable window: unexplored areas revealed, flight points, dungeon entrances, spirit healers, zone crossings, coordinates and zone level ranges. Replaces Leatrix Maps."},{"r","Maps",0,2},{"d","Maps",0,2,"Makes the map a movable, resizable window: unexplored areas revealed, flight points, dungeon entrances, spirit healers, zone crossings, coordinates and zone level ranges."},{"t","Merchant",0,2,"ZacUI's own merchant window: every item in one searchable list with usable / affordable filters, buyback, repair and sell-junk buttons. Blizzard's clicks and purchase prompts all still apply."},{"r","Merchant",0,2},{"d","Merchant",0,2,"ZacUI's own merchant window: every item in one searchable list with usable / affordable filters, buyback, repair and sell-junk buttons."},{"t","Merchant (Blizzard)",0,2,"Skins Blizzard's vendor window. Only visible when the ZacUI merchant window is off."},{"r","Merchant (Blizzard)",0,2},{"r","Skins Blizzard's vendor window.",0,2},{"r","Odds and ends",0,2},{"d","Odds and ends",0,2,"Durability, tickets, help, the coin-flip and roll popups, and the rest of the long tail."},{"r","Pet",0,2},{"d","Pet",0,2,"ZacUI's Pet page: your pet's name, level and family, a rotatable and zoomable model, and for hunters happiness, loyalty, experience and training points, plus the same stats and resistances as Blizzard's pet sheet."},{"r","Popups",0,2},{"r","StaticPopups and shared dialog chrome.",0,2},{"r","Professions",0,2},{"d","Professions",0,2,"A wide, searchable recipe list and detail pane for every profession, with a tab for each profession you know (Engineering, Alchemy, Cooking, First Aid...), Have materials / Skill-ups filters and Create / Create all."},{"r","PvP",0,2},{"r","Battleground scoreboard, queue windows and the world state bar.",0,2},{"t","Quest dialogue",0,2,"ZacUI's own quest pages: the NPC's quest list, the quest offer with objectives and rewards, the hand-in page with item counts, and the reward page where you pick your reward. Accept, decline, continue and complete go through Blizzard's own buttons."},{"r","Quest dialogue",0,2},{"d","Quest dialogue",0,2,"ZacUI's own quest pages: the NPC's quest list, the quest offer with objectives and rewards, the hand-in page with item counts, and the reward page where you pick your reward."},{"t","Quest log",0,2,"ZacUI's own quest log: quests down the left in collapsible zones with level tags, a search box and Unfinished / Group filters, and the selected quest on the right with objectives, description and rewards. Abandon, share and track work exactly as Blizzard's do."},{"r","Quest log",0,2},{"d","Quest log",0,2,"ZacUI's own quest log: quests down the left in collapsible zones with level tags, a search box and Unfinished / Group filters, and the selected quest on the right with objectives, description and rewards."},{"t","Quest log (Blizzard)",0,2,"Skins Blizzard's quest log. Only visible when the ZacUI quest log is off."},{"r","Quest log (Blizzard)",0,2},{"r","Skins Blizzard's quest log.",0,2},{"r","Quests & gossip",0,2},{"r","Quest pages, gossip, and the parchment text fix.",0,2},{"r","Raid",0,2},{"d","Raid",0,2,"The eight raid groups as flat cards: drag members between groups, right-click for the raid menu, plus Ready Check, All Assist, Raid Info and Convert."},{"r","Ready check",0,2},{"d","Ready check",0,2,"The raid utility popups: ready check, the master looter picker and the role poll."},{"r","Reputation",0,2},{"d","Reputation",0,2,"ZacUI's Reputation page: searchable factions with Hide inactive / At war filters, standing bars, and the At war / Inactive / Show as experience bar options."},{"r","Scoreboard",0,2},{"d","Scoreboard",0,2,"The battleground scoreboard: sortable columns including each battleground's own stats, All / Alliance / Horde filter, name search, class and faction colours, your row highlighted, winner banner and a Leave button."},{"t","Settings",0,2,"Blizzard's settings panel. Light touch by doctrine - it is already dark."},{"r","Settings",0,2},{"r","Blizzard's settings panel.",0,2},{"r","Skills",0,2},{"d","Skills",0,2,"ZacUI's Skills page: searchable skill list with collapsible groups, flat rank bars and Blizzard's unlearn prompt."},{"r","Social (Blizzard)",0,2},{"d","Social (Blizzard)",0,2,"Skins Blizzard's social window: the raid tab, ignore list and anything the ZacUI pages leave."},{"t","Social tabs",0,2,"The Friends / Who / Guild / Raid tabs and the Friends / Ignore tabs as full-size ZacUI tabs. They click Blizzard's own tabs underneath, so switching page still works in combat."},{"r","Social tabs",0,2},{"d","Social tabs",0,2,"The Friends / Who / Guild / Raid tabs and the Friends / Ignore tabs as full-size ZacUI tabs."},{"t","Spellbook",0,2,"ZacUI's own spellbook: every spell in one searchable list, filtered by school, with cooldowns, an all-ranks toggle and pet autocast. Click to cast, drag to your bars. In combat the list stays put (spells still cast) and unlocks when the fight ends."},{"r","Spellbook",0,2},{"d","Spellbook",0,2,"ZacUI's own spellbook: every spell in one searchable list, filtered by school, with cooldowns, an all-ranks toggle and pet autocast."},{"t","Spellbook (Blizzard)",0,2,"Skins Blizzard's spellbook. Only visible when the ZacUI spellbook is off."},{"r","Spellbook (Blizzard)",0,2},{"r","Skins Blizzard's spellbook.",0,2},{"t","Talents",0,2,"ZacUI's own talent window: all three trees side by side with prerequisite lines, dual-spec tabs with Activate, and preview Learn / Reset. Click to learn, right-click to remove a preview point, shift-click to link."},{"r","Talents",0,2},{"d","Talents",0,2,"ZacUI's own talent window: all three trees side by side with prerequisite lines, dual-spec tabs with Activate, and preview Learn / Reset."},{"r","Talents & AH",0,2},{"d","Talents & AH",0,2,"Load-on-demand windows: talents, trade skills, crafting, auction house, macros."},{"t","Trade",0,2,"ZacUI's own trade window: both sides' items as rows with quality borders, their money, who has accepted, and Trade / Cancel. Your gold, silver and copper boxes stay Blizzard's (the game locks them), framed into the window."},{"r","Trade",0,2},{"d","Trade",0,2,"ZacUI's own trade window: both sides' items as rows with quality borders, their money, who has accepted, and Trade / Cancel."},{"t","Trade (Blizzard)",0,2,"Skins Blizzard's trade window. Only visible when the ZacUI trade window is off."},{"r","Trade (Blizzard)",0,2},{"r","Skins Blizzard's trade window.",0,2},{"r","Trainer",0,2},{"d","Trainer",0,2,"ZacUI's own trainer window: every service in one searchable list with Blizzard's Available / Unavailable / Known filters, a detail pane with requirements and cost, and a Train all button that trains the next service you can afford with each click."},{"t","Trainer (Blizzard)",0,2,"Skins Blizzard's trainer window and the talent-clear prompt. Only visible when the ZacUI trainer is off."},{"r","Trainer (Blizzard)",0,2},{"r","Skins Blizzard's trainer window and the talent-clear prompt.",0,2},{"r","Who",0,2},{"d","Who",0,2,"ZacUI's own /who page: type a query and press Enter, sort by any column, then whisper, invite or add the player as a friend."},{"r","World map",0,2},{"r","World map, its chrome and the battlefield minimap.",0,2},{"c","How toggling behaves",0,3},{"d","How toggling behaves",0,3,"Turning a module ON applies it immediately. Turning one OFF needs a reload, because skinning strips Blizzard's artwork and there is nothing left to put back - ZacUI will not pretend otherwise."}},t={}}]=],
[=[return {c={"Animations","Try an animation"},e={{"c","Animations",0,1},{"t","Play animations",0,1,"Off makes every ZacUI animation an instant change: windows, frames and alerts simply appear and go. For anyone who finds motion distracting or uncomfortable."},{"r","Play animations",0,1},{"d","Play animations",0,1,"Off makes every ZacUI animation an instant change: windows, frames and alerts simply appear and go."},{"t","Play animations",0,1,"Higher is faster. At 1x every animation runs at the length it was set to."},{"r","Speed",0,1},{"r","Higher is faster.",0,1},{"t","Reset",0,1,"Animations on, at 1x speed."},{"r","Reset",0,1},{"c","Try an animation",0,2},{"t","Try an animation",0,2,"Pick a style and watch it in the preview - Show, Hide and Highlight are above it. This is a playground: each part of ZacUI has its own animation settings on its own page."},{"d","Try an animation",0,2,"Pick a style and watch it in the preview - Show, Hide and Highlight are above it."},{"r","Style",0,2},{"r","Slide",0,2},{"r","Duration",0,2},{"r","Delay",0,2},{"r","Easing",0,2},{"t","Repeat until hidden",0,2,"Pulse and Flash only: keep playing for as long as the frame is shown."},{"r","Repeat until hidden",0,2},{"r","Overshoot",0,2},{"r","Comes from",0,2},{"r","Distance",0,2},{"r","Below",0,2}},t={}}]=],
