[=[return {c={"Plates","Enemy plates","Friendly plates","Your target","Fading the rest","Priority mobs","Threat","Extras","Debuffs on enemy plates","Sunder / Expose","Under the bar","Simple aura row (older)","Simple aura row: what shows","Seen lately","Always show","Never show","Advanced","Sharing","Interrupt-ready cast bars","Textures","Bar background and border","States","Enemy size","Friendly size","Raid marker size","Bar colours","Threat bar","Cast bar colours","Target highlight","Target mark","Important plates","Sunder / Expose - look","Under the bar - look","Raid mod icons - size","NPC colours","Cast alerts","Plate font","Which plates","Name","Level","Health percent","Spell name on the cast bar","Threat bar percent","Mob's target under the bar","Quest mark","Priority mob count","Simple aura row stack count","Sunder / Expose - text","Under the bar - text","Cast bar","Soft target arrows","Sample plate on screen","Click box","Enemy name and marker","Friendly name and marker","Fine placement of the plate's parts","Raid mod icons","Sunder / Expose - position","Under the bar - position","Reset","Custom debuffs","Soft target","Fighting with the marker up (macro mode)","Crosshair","Crosshair look","Reticle frame","Colour by range and position","Leave these alone","Plate scripts","Mods (every plate)","Scripts (trigger-driven)","Hook reference"},e={{"c","Plates",1,1},{"r","Friendly NPC plates",1,1},{"r","Uses the game's own setting, so it applies out of combat.",1,1},{"r","Stacking plates",1,1},{"r","Plates push each other apart instead of overlapping.",1,1},{"r","Plate distance",1,1},{"r","How far away plates still show. 41 yards is the cap.",1,1},{"c","Enemy plates",1,2},{"r","Show the cast bar",1,2},{"r","Show the level on NPCs",1,2},{"r","Show the health percent",1,2},{"r","Class colour player bars",1,2},{"r","Enemy players' bars in their class colour.",1,2},{"r","Class colour player names",1,2},{"c","Friendly plates",1,3},{"t","Name only - no bar",1,3,"Friendly players are just a class-coloured name. Untick to give them real health bars (sizes on the Look tab)."},{"r","Name only - no bar",1,3},{"r","Friendly players are just a class-coloured name.",1,3},{"r","Show the cast bar",1,3},{"r","Show the level on NPCs",1,3},{"r","Show the health percent",1,3},{"r","Class colour player bars",1,3},{"r","Class colour player names",1,3},{"c","Your target",1,4},{"r","Highlight your target",1,4},{"r","A glow above and below your target's bar (colour on the Look tab).",1,4},{"r","Mouseover glow",1,4},{"r","A light sheen on the plate under your cursor.",1,4},{"r","Soft target counts as your target",1,4},{"d","Soft target counts as your target",1,4,"With no hard target, the mob your next ability would hit gets the full target treatment - glow, size and fade."},{"r","Mark your target's plate",1,4},{"d","Mark your target's plate",1,4,"An outline, corners or arrows round your target's bar (look on the Look tab)."},{"c","Fading the rest",1,5},{"r","Fade everything else",1,5},{"d","Fade everything else",1,5,"Every plate that is not your target drops to the opacity on the Look tab, so the one you are on is the only plate at full strength."},{"r","Bosses never fade",1,5},{"d","Bosses never fade",1,5,"A skull-level or world boss keeps its plate at full strength while you are on something else, and takes the important bar colour with threat on the border."},{"r","Mobs that never fade (comma between each)",1,5},{"r","Deathknight Captain",1,5},{"d","Deathknight Captain",1,5,"These never fade and take the important bar colour (threat on the border); no size change and no count."},{"t","Fade and size change only in combat",1,5,"Out of combat every plate stays full size and full opacity; the glow still marks your target. Stops always-on soft targeting from making plates pulse as you walk past mobs."},{"r","Fade and size change only in combat",1,5},{"d","Fade and size change only in combat",1,5,"Out of combat every plate stays full size and full opacity; the glow still marks your target."},{"r","Faded plates' opacity",1,5},{"r","Opacity in combat",1,5},{"r","Opacity",1,5},{"d","Opacity",1,5,"Every plate but your target while you have one. Until you set these they follow the switches above."},{"c","Priority mobs",1,6},{"t","Priority mobs",1,6,"Plates for these mobs never fade, grow, sit above every other plate and take their own colour - for adds that have to die first, like the Lightning Totems in Naxxramas. The click box stays the same size, so a /tar macro is the surest grab."},{"d","Priority mobs",1,6,"Plates for these mobs never fade, grow, sit above every other plate and take their own colour - for adds that have to die first, like the Lightning Totems in Naxxramas."},{"r","Highlight priority mobs",1,6},{"r","Mob names (comma between each)",1,6},{"r","Important plates take their own bar colour",1,6},{"d","Important plates take their own bar colour",1,6,"These mobs, the never-fade list and bosses: the bar takes the priority colour, and the threat colour moves to a border round it."},{"r","Count them mid-screen when two or more are up",1,6},{"d","Count them mid-screen when two or more are up",1,6,"A line like \"Embalming Slime x2\" while that many priority plates are up - one left stays quiet."},{"r","From how many",1,6},{"c","Threat",1,7},{"t","Colour bars by threat",1,7,"In combat the bar shows whose the mob is. Auto reads your stance - Defensive Stance or Bear Form means the tank colours."},{"r","Colour bars by threat",1,7},{"r","In combat the bar shows whose the mob is.",1,7},{"r","Colours for",1,7},{"r","Auto (by stance)",1,7},{"t","Aggro alarm glow",1,7,"Off by default. A steady sheen on plates whose threat is an alarm. In a group with many players that is most things you hit, which is why it defaults off."},{"r","Aggro alarm glow",1,7},{"r","Off by default. A steady sheen on plates whose threat is an alarm.",1,7},{"t","Threat bar under the health bar",1,7,"A short strip under the bar's right corner that fills with your threat on that mob - 100% is the moment it turns on you. While you tank your target, it shows whoever is closest to taking it, with their name. Hidden out of combat."},{"r","Threat bar under the health bar",1,7},{"d","Threat bar under the health bar",1,7,"A short strip under the bar's right corner that fills with your threat on that mob - 100% is the moment it turns on you."},{"r","Only on your target",1,7},{"r","Off shows it on every enemy you are fighting.",1,7},{"r","Show the percent on the threat bar",1,7},{"c","Extras",1,8},{"r","Show raid markers",1,8},{"r","Skull, cross and friends on the plate (spot on the Position tab).",1,8},{"r","Mob's target under the bar",1,8},{"r","Who each enemy is hitting, class coloured, in combat.",1,8},{"r","Cast target on the cast bar",1,8},{"r","'Fireball [Zacw]' instead of just 'Fireball'.",1,8},{"r","Quest mark",1,8},{"r","A gold ! next to mobs your quest log still needs.",1,8},{"r","Spell icon beside the cast bar",1,8},{"r","Smooth health",1,8},{"d","Smooth health",1,8,"The health fill glides to a new value instead of jumping (speed on the Animation tab)."},{"c","Debuffs on enemy plates",1,9},{"t","Debuffs on enemy plates",1,9,"Sunder stacks, Faerie Fire, curses, taunts and the rest, with their timers: the Sunder count big at the bar's right end, everything else as a row of small icons under the bar. Each group's look, text and spot are on their own tabs."},{"d","Debuffs on enemy plates",1,9,"Sunder stacks, Faerie Fire, curses, taunts and the rest, with their timers: the Sunder count big at the bar's right end, everything else as a row of small icons under the bar."},{"r","Show debuffs on enemy plates",1,9},{"r","One strip for the raid mods' plate icons",1,9},{"d","One strip for the raid mods' plate icons",1,9,"What the raid mods put on a mob's plate (Disarm, Enrage...) gathered into one row, scaled to match the debuff icons."},{"c","Sunder / Expose",1,10},{"r","Show this group",1,10},{"r","Which debuffs show in 