[=[return {c={"Talents","Spellbook"},e={{"c","Talents",0,1},{"t","Use ZacUI's talent tree",0,1,"On: the three trees side by side, with prerequisite arrows and ranks. Off: the game's own talent page."},{"r","Use ZacUI's talent tree",0,1},{"d","Use ZacUI's talent tree",0,1,"Click picks a rank, right-click takes a pick back, and Learn (it asks first) learns them all at once. Not in combat. Picks you never learned are dropped when the window closes. \"Game's view\" in the window's footer shows the game's own page until you next open it - switching spec lives there."},{"c","Spellbook",0,2},{"t","Use ZacUI's spellbook",0,2,"One searchable list of every spell, filtered by school, with every rank when you ask for it."},{"r","Use ZacUI's spellbook",0,2},{"d","Use ZacUI's spellbook",0,2,"\"All ranks\" in the book is the game's Show all spell ranks switch (not offered to warriors and rogues, as in the game's own book); each row casts its own rank. Turning the book off takes a /reload."}},t={}}]=],
