local flavor = ns.DetectFlavor and ns.DetectFlavor() or "era"
local class = UnitClass and select(2, UnitClass("player")) or nil
local out = { v = "3.0.21", locale = "enUS", flavor = flavor, class = class, pages = {} }
-- (a page is one text, or the lines every class has and this class's own)
for id, n in pairs((MAP[flavor] and class and MAP[flavor][class]) or {}) do
    if type(n) == "table" then out.pages[id] = { T[n[1]], T[n[2]] } else out.pages[id] = T[n] end
end
ns.SearchShipped = out
